  let left = 0;
  let total = 0;

  for (let right = 0; right < nums.length; right++) {
    counts.set(nums[right], (counts.get(nums[right]) || 0) + 1);

    while (Math.max(...counts.keys()) - Math.min(...counts.keys()) > 2) {
      const value = nums[left];
      counts.set(value, counts.get(value) - 1);
      if (counts.get(value) === 0) {
        counts.delete(value);
      }
      left++;
    }

    total += right - left + 1;
  }
  return total;
}

