function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 9);
  const style = Math.floor(rand() * 3);
  const nums = [];
  let current = 1 + Math.floor(rand() * 10);
  for (let i = 0; i < n; i++) {
    if (style === 0) {
      nums.push(1 + Math.floor(rand() * 6));
    } else if (style === 1) {
      current += Math.floor(rand() * 3) - 1;
      if (current < 1) current = 1;
      if (rand() < 0.03) current += Math.floor(rand() * 7);
      nums.push(current);
    } else {
      nums.push(rand() < 0.5 ? 1000000000 - Math.floor(rand() * 4) : 1 + Math.floor(rand() * 1000000000));
    }
  }
  return [nums];
}
